/** In-process store with TTL and LRU eviction. Fine for a single instance. */
export class MemoryStore implements CacheStore {
  private entries = new Map<string, { value: string; expiresAt: number }>();

  constructor(private maxEntries = 10_000) {}

  async get(key: string): Promise<string | null> {
    const entry = this.entries.get(key);
    if (!entry) return null;
    if (entry.expiresAt <= Date.now()) {
      this.entries.delete(key);
      return null;
    }
    // Re-insert to mark as most recently used.
    this.entries.delete(key);
    this.entries.set(key, entry);
    return entry.value;
  }

  async set(key: string, value: string, ttlSeconds: number): Promise<void> {
    this.entries.delete(key);
    this.entries.set(key, { value, expiresAt: Date.now() + ttlSeconds * 1000 });
    if (this.entries.size > this.maxEntries) {
      this.entries.delete(this.entries.keys().next().value!);
    }
  }

  async del(key: string): Promise<void> {
    this.entries.delete(key);
  }
}

export interface ProfileCacheOptions {
  store: CacheStore;
  ttlSeconds?: number;
  keyPrefix?: string;
  onError?: (err: unknown) => void;
}

export class ProfileCache<T> {
  private store: CacheStore;
  private ttlSeconds: number;
  private keyPrefix: string;
  private onError: (err: unknown) => void;
  private inFlight = new Map<string, Promise<T | null>>();
  private generation = new Map<string, number>();

  constructor(opts: ProfileCacheOptions) {
    this.store = opts.store;
    this.ttlSeconds = opts.ttlSeconds ?? 300;
    this.keyPrefix = opts.keyPrefix ?? "user-profile:v1:";
    this.onError = opts.onError ?? (() => {});
  }

  /**
   * Cache-aside read. Concurrent misses for the same user share one load.
   * A cache outage degrades to calling `load` directly rather than failing.
   */
  async get(userId: string, load: () => Promise<T | null>): Promise<T | null> {
    const key = this.keyPrefix + userId;

    try {
      const hit = await this.store.get(key);
      if (hit !== null) return JSON.parse(hit) as T;
    } catch (err) {
      this.onError(err);
    }

    const pending = this.inFlight.get(key);
    if (pending) return pending;

    const gen = this.generation.get(key) ?? 0;
    const promise = (async () => {
      const profile = await load();
      // Skip the write if the profile was invalidated while we were loading,
      // otherwise we'd re-cache the pre-update value.
      if (profile !== null && (this.generation.get(key) ?? 0) === gen) {
        try {
          await this.store.set(key, JSON.stringify(profile), this.ttlSeconds);
        } catch (err) {
          this.onError(err);
        }
      }
      return profile;
    })().finally(() => {
      if (this.inFlight.get(key) === promise) this.inFlight.delete(key);
    });

    this.inFlight.set(key, promise);
    return promise;
  }

  /** Call after any write to the profile (update, delete, avatar change, ...). */
  async invalidate(userId: string): Promise<void> {
    const key = this.keyPrefix + userId;
    this.generation.set(key, (this.generation.get(key) ?? 0) + 1);
    this.inFlight.delete(key);
    await this.store.del(key);
  }
}
